do $$
declare bad text;
begin
  -- identity: each code must still be the DK row of that name
  select string_agg(f.code, ', ') into bad from _fill_hotel f
   where not exists (select 1 from public.hotels x where x.hotel_code = f.code and x.name = f.name and x.country_code = 'DK');
  if bad is not null then raise exception 'hotels: code is no longer the exported DK row: %', bad; end if;
